"""Focused addition on the numerical stability of the physical-removal test."""
import json
from pathlib import Path
import review12_sections as previous
from review11_sections import supplementary
ROOT=Path(__file__).resolve().parent.parent
def add_section(doc,marker,paragraph,table,figure):
    if marker!='Q1_PRECISION_V13':return previous.add_section(doc,marker,paragraph,table,figure)
    a=json.loads((ROOT/'revision_13_2026-10-23/precision_summary.json').read_text());rows=a['rows']
    paragraph(doc,'Numerical stability of the nanometre contrasts is assessed separately from their detectability in noise. On the same eight phases at h=0.35 mm, the elastic systems are refactored with an alternative sparse-LU ordering and four residual-correction steps; the condensed active-contact equations are then polished at 80 decimal digits. This tests sensitivity to algebraic solution choices without converting the full FE assembly to arbitrary precision. A zero-removal reassembly checks the numerical null contrast. A radially weighted harmonic extension changes interior mesh coordinates while preserving the identical boundary polygon. Finally, halving pressure spacing from 0.02 to 0.01 mm repeats the physical-removal contrast on these same eight phases, independently of the 24-phase interface study.')
    bas=[r for r in rows if r['mode']=='baseline']
    reference={r['depth_um']:r['signal_rms_nm'] for r in bas}
    relative=100*max(r['control_change_rms_nm']/reference[r['depth_um']] for r in rows)
    paragraph(doc,'The repeated baseline contrasts are '+', '.join(f"{r['signal_rms_nm']:.6f}" for r in bas)+' nm RMS for 10 and 50 µm removal. Relative to these centred curves, maximum RMS changes across the two depths are '+', '.join(f"{max(r['control_change_rms_nm'] for r in rows if r['mode']==m):.6g} nm" for m in ['enhanced_algebra','weighted_morph','fine_interface'])+f' for enhanced algebra, alternative mesh extension and halved pressure spacing, respectively (Supplementary Table S21). The largest tested curve change is {relative:.3f}% of its same-depth baseline contrast. The largest zero-removal approach difference is '+f"{a['max_nominal_reassembly_change_nm']:.6g} nm. These are empirical numerical-stability controls, not rigorous bounds on the continuum or geometric-discretization error.")
    paragraph(doc,'The structural contrast must also be distinguished from an observable experimental signal. Its approximately 0.4–2.1 nm RMS is 48–250 times smaller than the assumed 100 nm per-sample noise. Numerical resolution of such a contrast does not establish its detectability or identify physical relief parameters. The controls preserve the eight-phase boundary geometry and do not certify unresolved corner contacts, the complete cycle, or the 102-phase P1 inverse operator.')
    supplementary('S21','Numerical controls for physical removal on the eight S20 phases at h=0.35 mm. Enhanced algebra uses alternative sparse-LU ordering, four elastic residual corrections and 80-digit condensed-contact polishing; the FE assembly remains float64. Weighted morphing fixes the identical boundary polygon. Fine interface halves pressure spacing on these same eight phases. Changes compare centred curves with the repeated baseline, not only their RMS magnitudes. These empirical changes are not total numerical-error bounds.',['Control','Depth µm','Signal RMS nm','Curve change RMS nm'],[[r['mode'].replace('_',' '),f"{r['depth_um']:.0f}",f"{r['signal_rms_nm']:.6f}",f"{r['control_change_rms_nm']:.6g}"] for r in rows],[4.7,2.2,4.8,4.7])
